import type { VideoRenderer } from "../../model/innertube.gen";
import { getText } from "../../model/text";
import { BadgeList } from "../badge/MetadataBadge";
import { ChannelName } from "../channel/ChannelName";
import styles from "./VideoMetaBlock.module.css";

export interface VideoMetaBlockProps {
  data: Pick<VideoRenderer, "shortViewCountText" | "viewCountText" | "publishedTimeText" | "shortBylineText" | "ownerBadges"> & {
    topStandaloneBadge?: unknown;
  };
  /** Shows the channel name above the metadata line. */
  showByline?: boolean;
}

/** The view count and publish date line of a video, with optional byline. */
export function VideoMetaBlock({ data, showByline }: VideoMetaBlockProps) {
  const views = getText(data.shortViewCountText ?? data.viewCountText);
  const published = getText(data.publishedTimeText);
  return (
    <div className={styles.metaBlock}>
      <div className={styles.metadata}>
        {showByline && (
          <div className={styles.byline}>
            <ChannelName name={data.shortBylineText} badges={data.ownerBadges} />
            <div className={styles.separator}>•</div>
          </div>
        )}
        <div className={styles.metadataLine}>
          {!!data.topStandaloneBadge && <BadgeList badges={[data.topStandaloneBadge as object]} />}
          {views && <span className={styles.item}>{views}</span>}
          {published && <span className={styles.item}>{published}</span>}
        </div>
      </div>
    </div>
  );
}
