import clsx from "clsx";
import { useDeferredValue, useRef } from "react";
import type { ItemSectionRenderer } from "../../model/innertube.gen";
import { useImpression } from "../../logging/impressions";
import { Renderer, RendererList } from "../../renderers/Renderer";
import styles from "./ItemSection.module.css";

/** Items rendered in the first commit of a new results page. */
const FIRST_BATCH = 4;

export interface ItemSectionProps {
  data: ItemSectionRenderer;
  /**
   * Renders the first few items right away and the rest in the
   * background, so that the first results show sooner.
   */
  progressive?: boolean;
  className?: string;
}

/** A section of results in a feed. */
export function ItemSection({ data, progressive, className }: ItemSectionProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const contents = data.contents as object[];
  const shown = useDeferredValue(contents, progressive ? contents.slice(0, FIRST_BATCH) : undefined);
  return (
    <div ref={ref} className={clsx(styles.section, className)} data-renderer="itemSectionRenderer">
      {data.header && (
        <div className={styles.header}>
          <Renderer data={data.header} />
        </div>
      )}
      <div className={styles.contents}>
        <RendererList items={shown} />
      </div>
    </div>
  );
}
